sys_variable_value.value:
(function execute(inputs, outputs) {

    outputs.next_class = '';

    function parseDate(value) {
        if (!value) {
            return null;
        }

        var raw;

        if (typeof value.getValue === 'function') {
            raw = value.getValue();
        } else {
            raw = value;
        }

        var text = String(raw).trim();
        var match;

        match = text.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);

        if (match) {
            return {
                year: parseInt(match[1], 10),
                month: parseInt(match[2], 10),
                day: parseInt(match[3], 10)
            };
        }

        match = text.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);

        if (match) {
            return {
                year: parseInt(match[3], 10),
                month: parseInt(match[2], 10),
                day: parseInt(match[1], 10)
            };
        }

        return null;
    }

    function pad(number) {
        return number < 10 ? '0' + number : String(number);
    }

    function dateKey(date) {
        return date.year + '-' +
            pad(date.month) + '-' +
            pad(date.day);
    }

    function daysInMonth(year, month) {
        return new Date(
            Date.UTC(year, month, 0)
        ).getUTCDate();
    }

    var start = parseDate(inputs.start_date);
    var current = parseDate(inputs.current_next_class);
    var end = parseDate(inputs.end_date);

    if (!start || !current || !inputs.recurrence) {
        return;
    }

    var recurrence = String(inputs.recurrence)
        .toLowerCase()
        .trim()
        .replace(/[\s_-]/g, '');

    var next;

    /*
     * Weekly recurrence
     */
    if (recurrence === 'weekly') {
        var currentUTC = Date.UTC(
            current.year,
            current.month - 1,
            current.day
        );

        var calculatedDate =
            new Date(currentUTC + (7 * 86400000));

        next = {
            year: calculatedDate.getUTCFullYear(),
            month: calculatedDate.getUTCMonth() + 1,
            day: calculatedDate.getUTCDate()
        };
    }

    /*
     * Monthly, quarterly and yearly recurrence
     */
    else {
        var monthsToAdd;

        if (recurrence === 'monthly') {
            monthsToAdd = 1;
        } else if (recurrence === 'quarterly') {
            monthsToAdd = 3;
        } else if (recurrence === 'yearly') {
            monthsToAdd = 12;
        } else {
            return;
        }

        var totalMonths =
            (current.year * 12) +
            (current.month - 1) +
            monthsToAdd;

        var nextYear = Math.floor(totalMonths / 12);
        var nextMonth = (totalMonths % 12) + 1;

        next = {
            year: nextYear,
            month: nextMonth,
            day: Math.min(
                start.day,
                daysInMonth(nextYear, nextMonth)
            )
        };
    }

    /*
     * Stop when the following occurrence exceeds End Date
     */
    if (end && dateKey(next) > dateKey(end)) {
        outputs.next_class = '';
        return;
    }

    var result = new GlideDate();
    result.setValue(dateKey(next));

    outputs.next_class = result;

})(inputs, outputs);

